sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float hexSize;
uniform float mode;
uniform float rotation;
uniform float gap;
uniform float edgeSoft;
layout(color) uniform half4 gapColor;
uniform float shadeVar;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float hash21(float2 p) {
    return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453);
}
float2 rot2(float2 p, float a) {
    float s = sin(a);
    float c = cos(a);
    return float2(p.x * c - p.y * s, p.x * s + p.y * c);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float2 ctr = size * 0.5;
    float2 p = rot2(coord - ctr, -radians(rotation));
    float q = (0.57735027 * p.x - 0.33333334 * p.y) / hexSize;
    float r = (0.6666667 * p.y) / hexSize;
    float cx = q;
    float cz = r;
    float cy = -cx - cz;
    float rx = floor(cx + 0.5);
    float ry = floor(cy + 0.5);
    float rz = floor(cz + 0.5);
    float dx = abs(rx - cx);
    float dy = abs(ry - cy);
    float dz = abs(rz - cz);
    if (dx > dy && dx > dz) rx = -ry - rz;
    else if (dy > dz) ry = -rx - rz;
    else rz = -rx - ry;
    float2 hc = float2(hexSize * (1.7320508 * rx + 0.8660254 * rz), hexSize * 1.5 * rz);
    float2 local = p - hc;
    float2 a = abs(local) / hexSize;
    float edge = max(a.x * 0.8660254 + a.y * 0.5, a.y);
    float m = 1.0 - smoothstep(1.0 - gap - edgeSoft, 1.0 - gap, edge);
    float4 samp = mode < 0.5 ? tex(rot2(hc, radians(rotation)) + ctr) : tex(rot2(local, radians(rotation)) + ctr);
    float shade = 1.0 + (hash21(float2(rx, rz)) - 0.5) * shadeVar * 2.0;
    float3 col = mix(float3(gapColor.rgb), unp(samp) * shade, m);
    return fin(c, float4(col * samp.a, samp.a), opacity);
}
